#!/usr/bin/env python3
"""Writes ui/ds/icon_svgs.luau: every icon in ui/assets/icons/ui as its SVG
source, by name, for ds/icon to draw as `code:` (a plugin lent the design
system loads no file outside its own folder, so the icons travel as code).
Run after adding or changing an icon there; the test
`the_design_system_s_icons_are_its_assets_inlined` says when it's due."""
import pathlib

here = pathlib.Path(__file__).resolve().parent.parent
icons = here / "ui" / "assets" / "icons" / "ui"
out = here / "ui" / "ds" / "icon_svgs.luau"
lines = [
    "-- Generated by tools/icon_svgs.py from ui/assets/icons/ui: don't edit.",
    "-- Each icon's SVG by its name, for ds/icon (drawn as `code:`, so a plugin",
    "-- lent the design system draws them too: it loads no file outside its",
    "-- own folder).",
    "",
    "return {",
]
for svg in sorted(icons.glob("*.svg")):
    text = svg.read_text().strip()
    assert "]==]" not in text, svg
    lines.append(f'\t["{svg.stem}"] = [==[{text}]==],')
lines.append("}")
out.write_text("\n".join(lines) + "\n")
print(f"{out}: {len(list(icons.glob('*.svg')))} icons")
